<script setup>
import { Link, router, useForm } from '@inertiajs/vue3';
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import PortalLayout from '../../Layouts/PortalLayout.vue';
import SectionTitle from '../../Components/SectionTitle.vue';
import { statusLabel } from '../../lib/status';

const props = defineProps({ event: Object, category: Object, entries: Array, pdams: Array });
const activeSection = ref('players');
const openPdam = ref(null);
const addingTeam = ref(false);
const minMembers = computed(() => props.category?.min_members || 1);
const maxMembers = computed(() => props.category?.max_members ?? null);
const maxTeams = computed(() => props.category?.max_teams_per_pd || 1);
const maxOfficials = computed(() => props.category?.max_officials_per_pd || 0);
const officialRoles = computed(() => props.category?.official_roles || []);
const teamRevisionEntry = computed(() => props.entries.find((entry) => entry.teams.some((team) => team.editable)));
const teamAdditionAvailableEntry = computed(() => props.entries.find((entry) => entry.team_addition_available));
const teamAdditionEntry = computed(() => addingTeam.value ? teamAdditionAvailableEntry.value : null);
const editableEntry = computed(() => teamRevisionEntry.value || teamAdditionEntry.value || props.entries.find((entry) => ['draft', 'revision_required'].includes(entry.verification_status) || (entry.verification_status === 'cancelled' && props.event.registration_open)));
const teamScopedRevision = computed(() => !!teamRevisionEntry.value && teamRevisionEntry.value.verification_status === 'pending');
const teamAddition = computed(() => !!teamAdditionEntry.value);
const lockedEntry = computed(() => teamAddition.value ? null : props.entries.find((entry) => ['verified', 'rejected'].includes(entry.verification_status) || (entry.verification_status === 'cancelled' && !props.event.registration_open) || (entry.verification_status === 'pending' && !entry.teams.some((team) => team.editable))));
const registeredTeams = computed(() => editableEntry.value?.teams.length || lockedEntry.value?.teams.length || 0);
const remainingTeams = computed(() => Math.max(0, maxTeams.value - registeredTeams.value));
const playerDocuments = { photo: 'Foto 3×4', registration_form: 'Form Pendaftaran', identity_card: 'KTP Pemain', pension_card: 'Kartu DAPENMA PAMSI / Dana Pensiun Lainnya', employee_decree: 'SK Karyawan Tetap' };
const officialDocuments = { photo: 'Foto 3×4', identity_card: 'KTP Official' };
const pdamLabel = (pdam) => [pdam.name, pdam.city, pdam.province].filter(Boolean).join(' · ');
const blankMember = () => ({ id: null, name: '', pdam_id: null, pdam_search: '', identity_type: 'nik', identity_number: '', documents: {}, document_errors: {} });
const normalizeMember = (member) => ({ ...blankMember(), ...member, pdam_search: member.pdam_name || '', documents: {}, existing_documents: member.documents || [] });
const blankMembers = () => Array.from({ length: minMembers.value }, blankMember);
const initialTeams = teamAddition.value ? [{ id: null, team_no: registeredTeams.value + 1, members: blankMembers() }] : editableEntry.value?.teams?.length ? editableEntry.value.teams.filter((team) => !teamScopedRevision.value || team.editable).map((team) => ({ id: team.id, team_no: team.team_no, verification_note: team.verification_note, members: team.members.map(normalizeMember) })) : [{ id: null, team_no: 1, members: blankMembers() }];
const initialOfficials = (teamScopedRevision.value || teamAddition.value) ? [] : editableEntry.value?.officials?.map((official) => ({ ...normalizeMember(official), role: official.role || officialRoles.value[0] || '' })) || [];
const form = useForm({ intent: 'draft', teams: initialTeams, officials: initialOfficials });
const officialCount = computed(() => teamAddition.value ? teamAdditionEntry.value?.officials.length || 0 : editableEntry.value ? form.officials.length : lockedEntry.value?.officials.length || 0);
const startTeamAddition = () => {
  addingTeam.value = true;
  activeSection.value = 'players';
  form.clearErrors();
  form.intent = 'submit';
  form.teams = [{ id: null, team_no: registeredTeams.value + 1, members: blankMembers() }];
  form.officials = [];
  requestAnimationFrame(() => document.querySelector('.registration-shell')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
};
const memberError = (teamIndex, memberIndex, field) => form.errors[`teams.${teamIndex}.members.${memberIndex}.${field}`];
const officialError = (index, field) => form.errors[`officials.${index}.${field}`];
const hasDocument = (member, key) => !!member.documents[key] || member.existing_documents?.includes(key);
const setFile = (member, key, event) => { const file = event.target.files?.[0] || null; if (file?.size > 1024 * 1024) { member.documents[key] = null; member.document_errors[key] = 'Ukuran maksimal 1 MB.'; event.target.value = ''; return; } delete member.document_errors[key]; member.documents[key] = file; };
const documentLabel = (key) => ({ photo: 'Foto 3×4', registration_form: 'Form Pendaftaran', identity_card: 'KTP', pension_card: 'Kartu Pensiun', employee_decree: 'SK Karyawan Tetap' }[key] || key);
const filteredPdams = (member) => { const search = member.pdam_search.trim().toLowerCase(); return props.pdams.filter((pdam) => !search || pdamLabel(pdam).toLowerCase().includes(search)).slice(0, 30); };
const selectPdam = (member, pdam) => { member.pdam_id = pdam.id; member.pdam_search = pdamLabel(pdam); openPdam.value = null; };
const closePdamOutside = (event) => { if (!event.target.closest('.pdam-field')) openPdam.value = null; };
onMounted(() => document.addEventListener('pointerdown', closePdamOutside));
onBeforeUnmount(() => document.removeEventListener('pointerdown', closePdamOutside));
const addMember = (team) => { if (maxMembers.value === null || team.members.length < maxMembers.value) team.members.push(blankMember()); };
const removeMember = (team, index) => { if (team.members.length > minMembers.value) team.members.splice(index, 1); };
const addTeam = () => { if (!teamScopedRevision.value && form.teams.length < maxTeams.value) form.teams.push({ id: null, team_no: form.teams.length + 1, members: blankMembers() }); };
const removeTeam = (index) => { if (form.teams.length > 1) form.teams.splice(index, 1); };
const addOfficial = () => { if (form.officials.length < maxOfficials.value) form.officials.push({ ...blankMember(), role: officialRoles.value[0] || '' }); };
const submit = (intent) => { form.intent = intent; form.post(`/pd/events/${props.event.code}/entries`, { preserveScroll: true, forceFormData: true }); };
const cancel = (id) => { if (confirm('Batalkan pendaftaran ini?')) router.delete(`/pd/entries/${id}`, { preserveScroll: true }); };
</script>

<template>
  <PortalLayout portal="pd">
    <div class="page-head"><SectionTitle eyebrow="Pendaftaran Cabor" :title="event.name" /><Link href="/pd/dashboard?section=cabor#cabor" class="back">← Kembali ke Registrasi Cabor</Link></div>

    <section class="competition-rules portal-card"><header><div><span>Aturan Pendaftaran</span><h3>{{ category?.name }}</h3></div><small>Ketentuan ini dikunci saat kompetisi dipublikasikan.</small></header><div class="rule-grid"><article><span>Format Pertandingan</span><strong>{{ event.format_label }}</strong><small>Format pelaksanaan ditetapkan panitia.</small></article><article><span>Kuota Tim PD</span><strong>{{ registeredTeams }} dari {{ maxTeams }} tim</strong><small>{{ remainingTeams ? `Masih dapat menambahkan ${remainingTeams} tim sebelum diajukan.` : 'Kuota tim telah terpakai.' }}</small></article><article><span>Komposisi Tim</span><strong>{{ maxMembers === null ? `Minimal ${minMembers} pemain` : minMembers === maxMembers ? `${minMembers} pemain per tim` : `${minMembers}–${maxMembers} pemain per tim` }}</strong><small>Jumlah pemain tidak dapat melewati ketentuan.</small></article><article><span>Official PD</span><strong>{{ officialCount }} dari {{ maxOfficials }} official</strong><small>{{ category?.official_can_compete ? 'Berlaku untuk seluruh tim; official boleh bertanding.' : 'Berlaku untuk seluruh tim; official tidak boleh merangkap pemain.' }}</small></article></div></section>

    <form v-if="(event.registration_open || editableEntry?.verification_status === 'revision_required' || teamScopedRevision || teamAddition) && !lockedEntry" class="registration-shell portal-card" @submit.prevent>
      <header class="form-head"><div><span>{{ teamAddition ? 'PENAMBAHAN TIM' : teamScopedRevision ? 'PERBAIKAN TIM' : 'FORM REGISTRASI PD' }}</span><h3>{{ teamAddition ? `Lengkapi Tim ${registeredTeams + 1}` : teamScopedRevision ? 'Lengkapi Perbaikan yang Diminta' : editableEntry ? 'Perbarui Data Peserta' : 'Lengkapi Data Peserta' }}</h3><p>{{ teamAddition ? 'Tim yang sudah terverifikasi tetap terkunci. Lengkapi dan ajukan hanya tim baru ini.' : teamScopedRevision ? 'Hanya tim yang diminta perbaikan yang dapat diubah. Tim lain tetap terkunci.' : 'Draft dapat disimpan tanpa lampiran lengkap. Semua dokumen wajib sebelum diajukan.' }}</p></div><div class="progress"><b>{{ form.teams.reduce((sum, team) => sum + team.members.length, 0) }}</b><small>Pemain</small></div></header>
      <nav class="form-tabs" aria-label="Bagian form"><button type="button" :class="{ active: activeSection === 'players' }" @click="activeSection = 'players'">Pemain <span>{{ form.teams.reduce((sum, team) => sum + team.members.length, 0) }}</span></button><button v-if="!teamScopedRevision && !teamAddition" type="button" :class="{ active: activeSection === 'officials' }" @click="activeSection = 'officials'">Official <span>{{ form.officials.length }}/{{ maxOfficials }}</span></button></nav>

      <div v-show="activeSection === 'players'" class="section-stack">
        <article v-for="(team, teamIndex) in form.teams" :key="team.id || teamIndex" class="team-card"><header><div><small>UNIT PESERTA</small><h4>Tim #{{ team.team_no || teamIndex + 1 }}</h4></div><button v-if="!teamScopedRevision && form.teams.length > 1" type="button" class="text-danger" @click="removeTeam(teamIndex)">Hapus Tim</button></header><p v-if="team.verification_note" class="team-feedback"><strong>Catatan Panitia</strong>{{ team.verification_note }}</p>
          <div v-for="(member, memberIndex) in team.members" :key="member.id || memberIndex" class="person-card">
            <div class="person-title"><b>{{ memberIndex + 1 }}</b><div><strong>Pemain {{ memberIndex + 1 }}</strong><small>Identitas dan dokumen pemain</small></div><button v-if="team.members.length > minMembers" type="button" class="text-danger" @click="removeMember(team, memberIndex)">Hapus</button></div>
            <div class="identity-grid"><label class="portal-field"><span>Nama Lengkap</span><input v-model="member.name" maxlength="120"><small v-if="memberError(teamIndex, memberIndex, 'name')" class="err">{{ memberError(teamIndex, memberIndex, 'name') }}</small></label><div class="portal-field pdam-field"><span>Asal PDAM</span><input v-model="member.pdam_search" type="search" autocomplete="off" placeholder="Cari nama PDAM, kota, atau provinsi" @focus="openPdam = `${teamIndex}-${memberIndex}`" @input="member.pdam_id = null; openPdam = `${teamIndex}-${memberIndex}`"><div v-if="openPdam === `${teamIndex}-${memberIndex}`" class="pdam-dropdown"><button v-for="pdam in filteredPdams(member)" :key="pdam.id" type="button" @mousedown.prevent="selectPdam(member, pdam)"><strong>{{ pdam.name }}</strong><small>{{ [pdam.city, pdam.province].filter(Boolean).join(' · ') }}</small></button><p v-if="!filteredPdams(member).length">PDAM tidak ditemukan.</p></div><small v-if="memberError(teamIndex, memberIndex, 'pdam_id')" class="err">{{ memberError(teamIndex, memberIndex, 'pdam_id') }}</small></div><label class="portal-field"><span>Jenis Identitas</span><select v-model="member.identity_type"><option value="nik">NIK</option><option value="kta">KTA</option></select></label><label class="portal-field"><span>Nomor NIK/KTA</span><input v-model="member.identity_number" maxlength="50" placeholder="Nomor tanpa spasi"><small v-if="memberError(teamIndex, memberIndex, 'identity_number')" class="err">{{ memberError(teamIndex, memberIndex, 'identity_number') }}</small></label></div>
            <div class="documents player-documents"><div class="documents-head"><strong>Kelengkapan Pemain</strong><small>JPG, PNG, atau PDF · maksimal 1 MB</small></div><label v-for="(label, key) in playerDocuments" :key="key" :class="['upload-row', { ready: hasDocument(member, key) }]"><span><b>{{ hasDocument(member, key) ? '✓' : '○' }}</b>{{ label }}</span><input type="file" accept=".jpg,.jpeg,.png,.pdf" @change="setFile(member, key, $event)"><em>{{ member.documents[key]?.name || (member.existing_documents?.includes(key) ? 'Sudah tersimpan' : 'Pilih file') }}</em><small v-if="member.document_errors[key] || memberError(teamIndex, memberIndex, `documents.${key}`)" class="err">{{ member.document_errors[key] || memberError(teamIndex, memberIndex, `documents.${key}`) }}</small></label></div>
          </div>
          <button v-if="maxMembers === null || team.members.length < maxMembers" type="button" class="portal-button secondary" @click="addMember(team)">+ Tambah Pemain</button>
        </article>
        <div v-if="!teamScopedRevision && !teamAddition" class="team-capacity"><button v-if="maxTeams > 1 && form.teams.length < maxTeams" type="button" class="portal-button secondary" @click="addTeam">Tambah Tim {{ form.teams.length + 1 }}</button><span>{{ form.teams.length < maxTeams ? `Tersisa ${maxTeams - form.teams.length} slot tim.` : `Kuota ${maxTeams} tim telah terpenuhi.` }}</span></div><small v-if="form.errors.teams" class="err">{{ form.errors.teams }}</small>
      </div>

      <div v-show="activeSection === 'officials'" class="section-stack"><div :class="['policy-alert', category?.official_can_compete ? 'allowed' : 'blocked']"><strong>{{ category?.official_can_compete ? 'Official boleh merangkap pemain' : 'Official dilarang merangkap pemain' }}</strong><span>Pemeriksaan memakai NIK/KTA pada seluruh registrasi aktif PD.</span></div>
        <article v-for="(official, index) in form.officials" :key="official.id || index" class="person-card official-card"><div class="person-title"><b>{{ index + 1 }}</b><div><strong>Official {{ index + 1 }}</strong><small>Identitas pendamping untuk seluruh tim PD pada kategori ini.</small></div><button type="button" class="text-danger" @click="form.officials.splice(index, 1)">Hapus</button></div><div class="identity-grid official"><label class="portal-field"><span>Nama Lengkap</span><input v-model="official.name" maxlength="120"></label><label class="portal-field"><span>Peran</span><select v-model="official.role"><option v-for="role in officialRoles" :key="role" :value="role">{{ role.replaceAll('_', ' ') }}</option></select></label><label class="portal-field"><span>Jenis Identitas</span><select v-model="official.identity_type"><option value="nik">NIK</option><option value="kta">KTA</option></select></label><label class="portal-field"><span>Nomor NIK/KTA</span><input v-model="official.identity_number" maxlength="50"></label></div><div class="documents official-documents"><div class="documents-head"><strong>Dokumen Official</strong><small>Foto dan identitas wajib jelas · maksimal 1 MB per dokumen</small></div><label v-for="(label, key) in officialDocuments" :key="key" :class="['upload-row', { ready: hasDocument(official, key) }]"><span><b>{{ hasDocument(official, key) ? '✓' : '○' }}</b><span><strong>{{ label }}</strong><small>{{ key === 'photo' ? 'Foto formal terbaru' : 'Dokumen identitas yang masih berlaku' }}</small></span></span><input type="file" accept=".jpg,.jpeg,.png,.pdf" @change="setFile(official, key, $event)"><em>{{ official.documents[key]?.name || (official.existing_documents?.includes(key) ? 'Dokumen tersimpan' : 'Pilih dokumen') }}</em><small v-if="official.document_errors[key] || officialError(index, `documents.${key}`)" class="err">{{ official.document_errors[key] || officialError(index, `documents.${key}`) }}</small></label></div><p v-if="official.playing_sports?.length" class="playing">Juga bermain: {{ official.playing_sports.join(', ') }}</p></article>
        <button v-if="form.officials.length < maxOfficials" type="button" class="portal-button secondary" @click="addOfficial">+ Tambah Official</button><p v-if="maxOfficials === 0" class="empty-note">Regulasi cabor tidak menyediakan kuota official.</p><small v-if="form.errors.officials" class="err">{{ form.errors.officials }}</small>
      </div>
      <div v-if="form.progress" class="upload-progress" role="status" aria-live="polite"><div><strong>Mengunggah dokumen</strong><span>{{ form.progress.percentage }}%</span></div><div class="upload-progress-track"><i :style="{ width: `${form.progress.percentage}%` }"></i></div><small>Jangan tutup halaman sampai proses selesai.</small></div>
      <footer class="form-actions"><button v-if="!teamScopedRevision && !teamAddition" type="button" class="portal-button secondary" :disabled="form.processing" @click="submit('draft')">Simpan Draft</button><button type="button" class="portal-button primary" :disabled="form.processing" @click="submit('submit')">{{ teamAddition ? 'Ajukan Tim Baru' : teamScopedRevision ? 'Kirim Ulang Perbaikan' : 'Ajukan Pendaftaran' }}</button></footer>
    </form>

    <section v-if="lockedEntry" class="registration-status portal-card"><div :class="['status-mark', lockedEntry.verification_status]" aria-hidden="true"><span>{{ lockedEntry.verification_status === 'verified' ? '✓' : lockedEntry.verification_status === 'pending' ? '◷' : lockedEntry.verification_status === 'rejected' ? '!' : '↻' }}</span></div><div class="status-copy"><div class="status-heading"><small>Status Pendaftaran · {{ statusLabel(lockedEntry.verification_status) }}</small></div><h3>{{ lockedEntry.verification_status === 'verified' ? 'Pendaftaran telah terverifikasi' : lockedEntry.verification_status === 'rejected' ? 'Pendaftaran ditolak panitia' : 'Pendaftaran sedang diperiksa panitia' }}</h3><p>{{ lockedEntry.verification_status === 'verified' ? 'Seluruh tim yang diajukan telah selesai diverifikasi. Data tetap terkunci untuk menjaga konsistensi pertandingan.' : lockedEntry.verification_status === 'rejected' ? 'Periksa catatan panitia pada roster sebelum mengajukan perbaikan.' : 'Data tim yang sudah diajukan tetap terkunci selama pemeriksaan pemain dan dokumen.' }}</p><div class="status-meta"><span><b>{{ registeredTeams }}</b> tim diajukan</span><span><b>{{ remainingTeams }}</b> slot tersisa</span><span><b>{{ lockedEntry.teams.reduce((sum, team) => sum + team.members.length, 0) }}</b> pemain</span></div></div><div v-if="teamAdditionAvailableEntry" class="team-addition-cta"><span>Kuota masih tersedia</span><strong>Daftarkan Tim {{ registeredTeams + 1 }}</strong><p>Tim sebelumnya tetap terkunci dan tidak perlu diajukan ulang.</p><button type="button" class="add-team-button" @click="startTeamAddition"><span>Tambah Tim {{ registeredTeams + 1 }}</span><i aria-hidden="true">→</i></button></div><div v-else-if="remainingTeams" class="status-next"><span>Langkah Berikutnya</span><p>Periode pendaftaran telah ditutup. Hubungi Admin bila penambahan tim masih diperlukan.</p></div></section>
    <section class="entry-list portal-card"><div class="roster-list-head"><div><span>Data Terkirim</span><h3>Roster yang Telah Diajukan</h3><p>Periksa status setiap tim, pemain, dokumen, dan catatan panitia dalam satu tampilan.</p></div><div class="roster-summary"><strong>{{ entries.reduce((sum, entry) => sum + entry.teams.length, 0) }}</strong><span>Total Tim</span></div></div><div class="roster-records"><article v-for="entry in entries" :key="entry.id" class="roster-record"><header><div><span class="record-eyebrow">Kontingen Terdaftar</span><strong>{{ entry.display_name }}</strong><small>{{ entry.teams.reduce((sum, team) => sum + team.members.length, 0) }} pemain · {{ entry.officials.length }} official</small></div><span :class="['registration-badge', entry.verification_status]">{{ entry.verification_status === 'pending' ? 'Pendaftaran dalam proses' : entry.verification_status === 'verified' ? 'Pendaftaran selesai' : statusLabel(entry.verification_status) }}</span></header><p v-if="entry.verification_note" class="entry-note">{{ entry.verification_note }}</p><section v-for="team in entry.teams" :key="team.id" :class="['roster-team', { attention: ['revision_required','rejected'].includes(team.status) }]"><div class="roster-team-head"><div><span>Unit Peserta</span><strong>{{ team.label }}</strong></div><span :class="['team-status', team.status]"><i aria-hidden="true">{{ team.status === 'verified' ? '✓' : team.status === 'rejected' ? '×' : team.status === 'revision_required' ? '!' : '•' }}</i>{{ statusLabel(team.status) }}</span></div><div v-if="team.verification_note" :class="['team-note', team.status]"><span>Catatan Panitia</span><p>{{ team.verification_note }}</p></div><details v-for="member in team.members" :key="member.id" class="roster-person" :open="member.verification_status === 'revision_required'"><summary><span><b>{{ member.name }}</b><small>{{ member.pdam_name || 'PDAM belum diisi' }} · {{ member.identity_type?.toUpperCase() }} {{ member.identity_number }}</small></span><span :class="['player-status', member.verification_status]"><i aria-hidden="true">{{ member.verification_status === 'verified' ? '✓' : member.verification_status === 'rejected' ? '×' : member.verification_status === 'revision_required' ? '!' : '•' }}</i>{{ statusLabel(member.verification_status) }}</span></summary><div><p v-if="member.verification_note" class="entry-note">{{ member.verification_note }}</p><nav><a v-for="document in member.document_links" :key="document.key" :href="document.url" target="_blank" rel="noopener">{{ documentLabel(document.key) }}</a></nav><small>Diperbarui {{ member.updated_at || '—' }}</small></div></details></section><section v-if="entry.officials.length" class="roster-officials"><strong>Official</strong><details v-for="official in entry.officials" :key="official.id"><summary>{{ official.name }} · {{ official.role.replaceAll('_', ' ') }}</summary><nav><a v-for="document in official.document_links" :key="document.key" :href="document.url" target="_blank" rel="noopener">{{ documentLabel(document.key) }}</a></nav></details></section><footer><button v-if="['draft','pending','revision_required','rejected'].includes(entry.verification_status)" class="text-danger" @click="cancel(entry.id)">Batalkan Pendaftaran</button></footer></article><p v-if="!entries.length" class="empty-note">Belum ada pendaftaran.</p></div></section>
  </PortalLayout>
</template>

